use std::fs
use std::collections::HashMap

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|p| p.to_string()).collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "balance" {
            let n = parts[1]
            if acc.contains_key(n) {
                println("${acc[n]}")
            } else {
                println("error: unknown account ${n}")
            }
        } else if cmd == "open" {
            let n = parts[1]
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if acc.contains_key(n) {
                println("error: duplicate account")
            } else {
                acc.insert(n, amt)
                println("ok")
            }
        } else if cmd == "deposit" || cmd == "withdraw" {
            let n = parts[1]
            let amt: int = parts[2].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(n) {
                println("error: unknown account ${n}")
            } else {
                let bal: int = acc[n]
                if cmd == "deposit" {
                    acc.insert(n, bal + amt)
                    println("ok")
                } else if bal < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(n, bal - amt)
                    println("ok")
                }
            }
        } else if cmd == "transfer" {
            let f = parts[1]
            let t = parts[2]
            let amt: int = parts[3].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(f) {
                println("error: unknown account ${f}")
            } else if !acc.contains_key(t) {
                println("error: unknown account ${t}")
            } else if f == t {
                println("error: same account")
            } else {
                let fb: int = acc[f]
                let tb: int = acc[t]
                if fb < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(f, fb - amt)
                    acc.insert(t, tb + amt)
                    println("ok")
                }
            }
        }
    }
    let mut keys: Vec<string> = []
    for k in acc.keys() {
        keys.push(k)
    }
    keys.sort()
    for k in keys {
        println("${k} ${acc[k]}")
    }
}

